// Add to log: send each of your Telegram replies to the check-in service and prepare a reply.
// Talks to src/careerlog/api.py and reports exactly what the service answered.

const config = $('Config').first().json;
const expectedChatId = String(config.chatId);
const checkinUrl = 'http://127.0.0.1:8765/entries';

const updates = $input.first().json.result || [];
const staticData = $getWorkflowStaticData('global');
let maxUpdateId = staticData.lastUpdateId || 0;

const replies = [];

for (const update of updates) {
  if (update.update_id > maxUpdateId) {
    maxUpdateId = update.update_id;
  }

  const message = update.message;
  if (!message || !message.text) continue;
  if (String(message.chat && message.chat.id) !== expectedChatId) continue;

  const text = message.text.trim();
  if (!text) continue;

  let replyText;
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: checkinUrl,
      headers: { 'X-Token': config.checkinToken, 'Content-Type': 'application/json' },
      body: { message: text },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: 10000,
    });
    const body = response.body || {};
    if (response.statusCode === 201) {
      replyText = 'Added to ' + body.project + '.';
    } else if (response.statusCode === 200 && body.duplicate) {
      replyText = 'Already in your log.';
    } else if (response.statusCode === 401) {
      replyText = 'Not added: bad or missing token. Check checkinToken in the Config node.';
    } else {
      replyText = 'Not added: ' + (body.error || ('the service answered ' + response.statusCode));
    }
  } catch (error) {
    replyText = 'Not added: the check-in service did not answer. Is it running?';
  }

  replies.push({ json: { chatId: expectedChatId, text: replyText, originalText: text } });
}

if (maxUpdateId > (staticData.lastUpdateId || 0)) {
  staticData.lastUpdateId = maxUpdateId;
}

// Tell Telegram these messages are done, so it stops sending them again even if
// n8n forgets its place (for example after a manual run or a restart).
if (updates.length) {
  try {
    await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.telegram.org/bot' + config.botToken + '/getUpdates',
      qs: { offset: maxUpdateId + 1, limit: 1, timeout: 0 },
      json: true,
    });
  } catch (error) {
    // the stored offset still protects the next run
  }
}

return replies.length
  ? replies
  : [{ json: { chatId: expectedChatId, text: null, skip: true } }];

// Make reply – just pass through the prepared reply (filter out skips)
const items = $input.all();
return items.filter(item => !item.json.skip && item.json.text);
